const methods={pos:['position','মূলবিন্দু চিহ্নিত করো। সেখান থেকে বিন্দুতে যাওয়ার তীরের উপাংশ লেখো।'],sum:['triangle','তীরগুলো মাথা-লেজে বসাও। প্রথম লেজ আর শেষ মাথার অবস্থান তুলনা করো।'],speed:['river','পাড় বরাবর ও প্রস্থ বরাবর দুটি অক্ষ নাও। নৌকার উপাংশের সঙ্গে স্রোতের উপাংশ যোগ করে লব্ধির দৈর্ঘ্য নাও।'],drift:['river','আগে প্রস্থ বরাবর বেগ দিয়ে পারাপারের সময় বার করো। সেই সময় ধরে পাড় বরাবর নিট বেগে কতটা সরবে?'],time:['river','প্রস্থকে লব্ধির মান দিয়ে নয়, প্রস্থ বরাবর উপাংশ দিয়ে ভাগ করো। তুলনার আগে একক এক করো।'],aim:['river','সোজা বিপরীতে পৌঁছাতে ভাটির সরণ থাকা চলবে না। উজানমুখী উপাংশ ও স্রোতের জন্য একটি সমীকরণ লেখো।'],meet:['river','নৌকার পৌঁছানোর সময় আর অন্য ব্যক্তি বা গাড়ির সময়সীমা আলাদা করে একই এককে লেখো।'],relative:['triangle','পর্যবেক্ষকের বেগ উল্টে যোগ করো। আপেক্ষিক বেগ থেকে প্রকৃত বেগে ফিরতে সেই যোগের বিপরীত ধাপ নাও।'],rain:['rain','খাড়া দিকে বৃষ্টি আর পথে পর্যবেক্ষকের বেগ আঁকো। আপেক্ষিক বেগে আনুভূমিক ও উল্লম্ব উপাংশ কোন কোণ দেয়?'],collision:['triangle','সংঘর্ষের আগে ও পরে সিস্টেমের ভরবেগ লিখে অক্ষ ধরে তুলনা করো। গতিশক্তিও সংরক্ষিত কি না দেখো।'],cross:['axes','একই পাদবিন্দুতে তীর দুটি বসাও। ডান হাতের নিয়মে ক্রম বদলে লম্ব দিকটি তুলনা করো।'],force:['resolve','প্রতিটি বলের x ও y উপাংশ আলাদা কলামে লেখো। চিহ্নসহ যোগ করে দিক ও মান বিচার করো।'],dot:['projection','সমসঙ্গী উপাংশ গুণ করে যোগ করো। কোণ বা লম্বতার শর্তের সঙ্গে এই রাশিটি মেলাও।'],angle:['projection','ডট গুণফল ও দুই ভেক্টরের দৈর্ঘ্য আলাদা বার করো। তাদের অনুপাত থেকে কোণ নির্ণয় করো।'],right:['triangle','তিন বাহুর দৈর্ঘ্যের বর্গ তুলনা করো। সবচেয়ে বড়টির বিপরীত কোণ সমকোণ কি না যাচাই করো।'],plane:['axes','দুটি তীরের তলের লম্ব দিক নাও। তৃতীয় তীরটির সেই দিকে উপাংশ আছে কি না পরীক্ষা করো।'],area:['area','সন্নিহিত বাহু আর কর্ণ গুলিয়ে ফেলো না। ভূমি ও লম্ব উচ্চতার গুণফলকে ক্রস গুণফলের সঙ্গে মেলাও।'],div:['flux','ক্ষেত্রের x, y ও z উপাংশ নিজ নিজ চলক অনুযায়ী অন্তরিত করো। তিনটি পরিবর্তন একসঙ্গে বিচার করো।'],curl:['curl','একটি ছোট বন্ধ পথ কল্পনা করো। কার্লের প্রতিটি উপাংশে কোন দুই আংশিক অন্তরকের পার্থক্য লাগবে লেখো।'],grad:['field','একটি স্কেলার মান থেকে শুরু করো। তিন অক্ষ বরাবর আলাদা পরিবর্তনের হার কোন দিকের একক তীরের সঙ্গে বসবে?'],unit:['unit','তীরের মান ও দিক আলাদা করে ভাবো। মান নির্ণয়ে উপাংশগুলোর বর্গ ব্যবহার করো।'],work:['projection','সরণের দিকে বলের উপাংশ ভাবো। কাজ, বল ও টর্কের সংজ্ঞায় কোথায় ডট বা ক্রস গুণফল লাগে দেখো।'],pull:['resolve','বলকে সমান্তরাল ও লম্ব উপাংশে ভাগ করো। কোণ বদলালে কোন উপাংশটি বাড়ে?'],period:['circle','একটি পূর্ণ চক্রের শুরু ও শেষে অবস্থা তুলনা করো। সময়, দশা এবং সাম্যাবস্থান আলাদা করে চিহ্নিত করো।'],axes:['axes','তিনটি স্বাধীন দিক এঁকে অক্ষগুলো চিহ্নিত করো। প্রতিটির দিক ও দৈর্ঘ্য আলাদা করে ভাবো।'],line:['unit','একই রেখা বা সমান্তরাল রেখায় তীর বসিয়ে দিক ও দৈর্ঘ্যের শর্ত দুটি আলাদা করো।'],field:['field','ক্ষেত্রের দুটি ভিন্ন বিন্দু ভাবো। প্রতিটি বিন্দুতে কী তথ্য দিতে হয়—মান, না মান ও দিক?'],projection:['projection','যে দিকে অভিক্ষেপ প্রয়োজন তার একক ভেক্টর নাও। অন্য তীরটির মাথা থেকে ভিত্তিতে লম্ব নামাও।'],distance:['triangle','একই মূলবিন্দু থেকে দুই অবস্থান লেখো। তাদের পার্থক্যের দৈর্ঘ্য আর ভাঙা পথের দৈর্ঘ্য আলাদা করো।'],spin:['circle','ঘূর্ণন অক্ষ থেকে দূরত্বটি চিহ্নিত করো। রৈখিক আর কৌণিক রাশির সম্পর্ক লেখো।'],lever:['area','ঘূর্ণন অক্ষ থেকে বলের ক্রিয়ারেখার লম্ব দূরত্ব দেখো।'],circle:['circle','বৃত্তের বিন্দুতে স্পর্শক ও কেন্দ্রের দিকে ব্যাসার্ধ আঁকো। বেগ ও ত্বরণ কোন দিকে?'],balance:['resolve','বস্তুর ওপর সব বল এবং তাদের প্রয়োগবিন্দু চিহ্নিত করো। সাম্য বা ত্বরণের শর্ত পরীক্ষা করো।'],humidity:['volume','বায়ুর নমুনায় জলীয় বাষ্পের পরিমাণ ভাবো। তাপমাত্রা বদলালে সম্পৃক্ততার শর্ত কীভাবে বদলায়?'],volume:['volume','সমান সংখ্যক কণার দুটি নমুনা ভাবো। তাপমাত্রা ও প্রতি কণার গড় গতিশক্তির সম্পর্ক লেখো।'],spring:['unit','সাম্য দৈর্ঘ্য ও প্রসারিত দৈর্ঘ্যের পার্থক্য চিহ্নিত করো। বলের সঙ্গে পরিবর্তনটির সম্পর্ক দেখো।'],pitch:['circle','একটি পূর্ণ পাকের জন্য অক্ষ বরাবর সরণ চিহ্নিত করো। পাঠ ও ত্রুটি আলাদা করে লেখো।'],flow:['flux','প্রবাহের পাশাপাশি দুটি পথ চিন্তা করো। কণার বেগ ও দিক স্থানে স্থানে কীভাবে বদলাচ্ছে?'],law:['field','পর্যবেক্ষণ, স্বীকৃত অনুমান আর পরিমাপযোগ্য রাশির মধ্যে পার্থক্য করো। প্রশ্নে কোন ধারণাটি চাওয়া হয়েছে?']};
export const guideFor=(n,j)=>guides[n-1]?.[j]??methods[rows[n-16][j]];
